import{_ as a,a0 as d,w as r,s as p,ao as n,I as s,a1 as l,A as o,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux 終端下的多媒體應用 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 終端下的多媒體應用 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 終端下的多媒體應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 終端下的多媒體應用 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180111 Multimedia Apps for the Linux Console","title":"Linux 終端下的多媒體應用","tag":"201802","desc":""},"relativePath":"201802/20180111 Multimedia Apps for the Linux Console.md","filePath":"[post].md"}'),u={name:"201802/20180111 Multimedia Apps for the Linux Console.md"};function b(f,e,g,m,c,k){const t=d("Link");return r(),p("div",null,[e[38]||(e[38]=n(`<h1 id="linux-終端下的多媒體應用" tabindex="-1">Linux 終端下的多媒體應用 <a class="header-anchor" href="#linux-終端下的多媒體應用" aria-label="Permalink to “Linux 終端下的多媒體應用”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/multimedia.jpg?itok=v-XrnKRB" alt=""></p><blockquote><p>Linux 終端是支持多媒體的，所以你可以在終端裏聽音樂，看電影，看圖片，甚至是閲讀 PDF。</p></blockquote><p>在我的上一篇文章裏，我們瞭解到 Linux 終端是可以支持多媒體的。是的，這是真的！你可以使用 Mplayer、fbi 和 fbgs 來實現不打開 X 會話就聽音樂、看電影、看照片，甚至閲讀 PDF。此外，你還可以通過 CMatrix 來體驗黑客帝國（Matrix）風格的屏幕保護。</p><p>不過你可能需要對系統進行一些修改才能達到前面這些目的。下文的操作都是在 Ubuntu 16.04 上進行的。</p><h3 id="mplayer" tabindex="-1">MPlayer <a class="header-anchor" href="#mplayer" aria-label="Permalink to “MPlayer”">​</a></h3><p>你可能會比較熟悉功能豐富的 MPlayer。它支持幾乎所有格式的視頻與音頻，並且能在絕大部分現有的平台上運行，像 Linux、Android、Windows、Mac、Kindle、OS/2 甚至是 AmigaOS。不過，要在你的終端運行 MPlayer 可能需要多做一點工作，這些工作與你使用的 Linux 發行版有關。來，我們先試着播放一個視頻：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mplayer [視頻文件名]</span></span></code></pre></div><p>如果上面的命令正常執行了，那麼很好，接下來你可以把時間放在瞭解 MPlayer 的常用選項上了，譬如設定視頻大小等。但是，有些 Linux 發行版在對<ruby>幀緩衝<rt>framebuffer</rt></ruby>的處理方式上與早期的不同，那麼你就需要進行一些額外的設置才能讓其正常工作了。下面是在最近的 Ubuntu 發行版上需要做的一些操作。</p><p>首先，將你自己添加到 <code>video</code> 用户組。</p><p>其次，確認 <code>/etc/modprobe.d/blacklist-framebuffer.conf</code> 文件中包含這樣一行：<code>#blacklist vesafb</code>。這一行應該默認被註釋掉了，如果不是的話，那就手動把它註釋掉。此外的其他模組行需要確認沒有被註釋，這樣設置才能保證其他那些模組不會被載入。注：如果你想要更深入的利用<ruby>幀緩衝<rt>framebuffer</rt></ruby>，這些針對你的顯卡的模組可以使你獲得更好的性能。</p><p>然後，在 <code>/etc/initramfs-tools/modules</code> 的結尾增加兩個模組：<code>vesafb</code> 和 <code>fbcon</code>，並且更新 iniramfs 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/initramfs-tools/modules</span></span>
<span class="line"><span> # List of modules that you want to include in your initramfs.</span></span>
<span class="line"><span> # They will be loaded at boot time in the order below.</span></span>
<span class="line"><span> fbcon</span></span>
<span class="line"><span> vesafb</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo update-initramfs -u</span></span></code></pre></div>`,13)),s("p",null,[l(t,{href:"https://www.mjmwired.net/kernel/Documentation/fb/fbcon.txt"},{default:o(()=>[...e[0]||(e[0]=[i("fbcon",-1)])]),_:1}),e[1]||(e[1]=i(" 是 Linux ",-1)),e[2]||(e[2]=s("ruby",null,[i("幀緩衝"),s("rt",null,"framebuffer")],-1)),e[3]||(e[3]=i("終端，它運行在",-1)),e[4]||(e[4]=s("ruby",null,[i("幀緩衝"),s("rt",null,"framebuffer")],-1)),e[5]||(e[5]=i("之上併為其增加圖形功能。而它需要一個",-1)),e[6]||(e[6]=s("ruby",null,[i("幀緩衝"),s("rt",null,"framebuffer")],-1)),e[7]||(e[7]=i("設備，這則是由 ",-1)),e[8]||(e[8]=s("code",null,"vesafb",-1)),e[9]||(e[9]=i(" 模組來提供的。",-1))]),e[39]||(e[39]=n('<p>接下來，你需要修改你的 GRUB2 配置。在 <code>/etc/default/grub</code> 中你將會看到類似下面的一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GRUB_CMDLINE_LINUX_DEFAULT=&quot;quiet splash&quot;</span></span></code></pre></div><p>它也可能還會有一些別的參數，不用管它，在其後加上 <code>vga=789</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GRUB_CMDLINE_LINUX_DEFAULT=&quot;quiet splash vga=789&quot;</span></span></code></pre></div><p>重啓之後進入你的終端（<code>Ctrl+Alt+F1</code>）（LCTT 譯註：在某些發行版中 <code>Ctrl+Alt+F1</code> 默認為圖形界面，可以嘗試 <code>Ctrl+Alt+F2</code>），然後就可以嘗試播放一個視頻了。下面的命令指定了 <code>fbdev2</code> 為視頻輸出設備，雖然我還沒弄明白如何去選擇用哪個輸入設備，但是我用它成功過。默認的視頻大小是 320x240，在此我給縮放到了 960：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mplayer -vo fbdev2 -vf scale -zoom -xy 960 AlienSong_mp4.mov</span></span></code></pre></div><p>來看圖 1。粗糙的畫面是由於我原視頻的質量不高，而不是 MPlayer 的顯示問題。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/fig-1_3.jpg?itok=PtSoKepn" alt="圖 1 播放視頻"></p><p>MPlayer 可以播放 CD、DVD 以及網絡視頻流，並且還有一系列的回放選項，這些將作為作業留給大家自己去發現。</p><h3 id="fbi-圖片查看器" tabindex="-1">fbi 圖片查看器 <a class="header-anchor" href="#fbi-圖片查看器" aria-label="Permalink to “fbi 圖片查看器”">​</a></h3>',10)),s("p",null,[e[11]||(e[11]=s("code",null,"fbi",-1)),e[12]||(e[12]=i(" 是一個幀緩衝圖片查看器。在大部分的 Linux 發行版中，它被包含在 ",-1)),l(t,{href:"https://www.kraxel.org/blog/linux/fbida/"},{default:o(()=>[...e[10]||(e[10]=[i("fbida",-1)])]),_:1}),e[13]||(e[13]=i(" 包裏。它原生支持一些常見的圖片格式，而如果你安裝了 ",-1)),e[14]||(e[14]=s("code",null,"convert",-1)),e[15]||(e[15]=i("（來自於 Image Magick），那麼它還能借此打開一些其他格式。最簡單的用法是用來查看一個圖片文件：",-1))]),e[40]||(e[40]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fbi 文件名</span></span></code></pre></div><p>你可以使用方向鍵來在大圖片中移動視野，使用 <code>+</code> 和 <code>-</code> 來縮放，或者使用 <code>r</code> 或 <code>l</code> 來向右或向左旋轉 90 度。<code>Escape</code> 鍵則可以關閉查看的圖片。此外，你還可以給 <code>fbi</code> 一個文件列表來實現幻燈播放：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fbi --list 文件列表.txt</span></span></code></pre></div><p><code>fbi</code> 還支持自動縮放。還可以使用 <code>-a</code> 選項來控制縮放比例。<code>--autoup</code> 和 <code>--autodown</code> 則是用於告知 <code>fbi</code> 只進行放大或者縮小。要調整圖片切換時淡入淡出的時間則可以使用 <code>--blend [時間]</code> 來指定一個以毫秒為單位的時間長度。使用 <code>k</code> 和 <code>j</code> 鍵則可以切換文件列表中的上一張或下一張圖片。</p><p><code>fbi</code> 還提供了命令來為你瀏覽過的文件創建文件列表，或者將你的命令導出到文件中，以及一系列其它很棒的選項。你可以通過 <code>man fbi</code> 來查閲完整的選項列表。</p><h3 id="cmatrix-終端屏保" tabindex="-1">CMatrix 終端屏保 <a class="header-anchor" href="#cmatrix-終端屏保" aria-label="Permalink to “CMatrix 終端屏保”">​</a></h3>',6)),s("p",null,[e[17]||(e[17]=s("ruby",null,[i("黑客帝國"),s("rt",null,"The Matrix")],-1)),e[18]||(e[18]=i("屏保仍然是我非常喜歡的屏保之一（如圖 2），僅次於",-1)),e[19]||(e[19]=s("ruby",null,[i("彈跳牛"),s("rt",null,"bouncing cow")],-1)),e[20]||(e[20]=i("。",-1)),l(t,{href:"http://www.asty.org/cmatrix/"},{default:o(()=>[...e[16]||(e[16]=[i("CMatrix",-1)])]),_:1}),e[21]||(e[21]=n(" 可以在終端運行。要運行它只需輸入 <code>cmatrix</code>，然後可以用 <code>Ctrl+C</code> 來停止運行。執行 <code>cmatrix -s</code> 則會啓動屏保模式，這樣的話，按任意鍵都會直接退出。<code>-C</code> 參數可以設定顏色，譬如綠色（<code>green</code>）、紅色（<code>red</code>）、藍色（<code>blue</code>）、黃色（<code>yellow</code>）、白色（<code>white</code>）、紫色（<code>magenta</code>）、青色（<code>cyan</code>）或者黑色（<code>black</code>）。",25))]),e[41]||(e[41]=n('<p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/fig-2_0.jpg?itok=E3f26R7w" alt="圖 2 黑客帝國屏保"></p><p>CMatrix 還支持異步按鍵，這意味着你可以在它運行的時候改變設置選項。</p><p><code>-B</code> 設置全部使用粗體，而 <code>-b</code>（LCTT 譯註：原文誤為 <code>-B</code>）則可以設置部分字體加粗。</p><h3 id="fbgs-pdf-閲讀器" tabindex="-1">fbgs PDF 閲讀器 <a class="header-anchor" href="#fbgs-pdf-閲讀器" aria-label="Permalink to “fbgs PDF 閲讀器”">​</a></h3><p>看起來，PDF 文檔是普遍流行且無法避免的，而且 PDF 比它之前的功能好了很多，譬如超鏈接、複製粘貼以及更好的文本搜索功能等。<code>fbgs</code> 是 <code>fbida</code> 包中提供的一個 PDF 閲讀器。它可以設置頁面大小、分辨率、指定頁碼以及絕大部分 <code>fbi</code> 所提供的選項，當然除了一些在 <code>man fbgs</code> 中列舉出來的不可用選項。我主要用到的選項是頁面大小，你可以選擇 <code>-l</code>、<code>xl</code> 或者 <code>xxl</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fbgs -xl annoyingpdf.pdf</span></span></code></pre></div>',6)),s("p",null,[e[23]||(e[23]=i("歡迎通過 Linux 基金會與 edX 免費提供的",-1)),l(t,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:o(()=>[...e[22]||(e[22]=[i("“Linux 入門”",-1)])]),_:1}),e[24]||(e[24]=i("課程學習更多 Linux 知識。",-1))]),e[42]||(e[42]=s("hr",null,null,-1)),s("p",null,[e[26]||(e[26]=i("via: ",-1)),l(t,{href:"https://www.linux.com/learn/intro-to-linux/2018/1/multimedia-apps-linux-console"},{default:o(()=>[...e[25]||(e[25]=[i("https://www.linux.com/learn/intro-to-linux/2018/1/multimedia-apps-linux-console",-1)])]),_:1})]),s("p",null,[e[30]||(e[30]=i("作者：",-1)),l(t,{href:"https://www.linux.com/users/cschroder"},{default:o(()=>[...e[27]||(e[27]=[i("Carla Schroder",-1)])]),_:1}),e[31]||(e[31]=i(" 譯者：",-1)),l(t,{href:"https://github.com/Yinr"},{default:o(()=>[...e[28]||(e[28]=[i("Yinr",-1)])]),_:1}),e[32]||(e[32]=i(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[29]||(e[29]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[35]||(e[35]=i("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[33]||(e[33]=[i("LCTT",-1)])]),_:1}),e[36]||(e[36]=i(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:o(()=>[...e[34]||(e[34]=[i("Linux中國",-1)])]),_:1}),e[37]||(e[37]=i(" 榮譽推出",-1))])])}const y=a(u,[["render",b]]);export{C as __pageData,y as default};
